save(395,dict(paragraphs=['Johny Takkedasila is a Telugu poet, fiction writer, critic and translator from Pulivendula, Andhra Pradesh, whose writing also spans Hindi and English. His Telugu critical work Vivechani received the Sahitya Akademi Yuva Puraskar in 2023. His books include Nadaka, published by Ukiyoto.','In “Sometimes I Freeze,” emotional paralysis becomes stone, wounded breath and a body struggling to move. Blood, tears, fire and rain carry the poem through a series of transformations, until its closing address joins pain with gratitude toward the person who sets the speaker in motion.'],sources=[source('Sahitya Akademi — Yuva Puraskar recipients','https://sahitya-akademi.gov.in/awards/yuva_samman_suchi.jsp',['Telugu, 2023, Vivechani (Criticism), Johny Takkedasila; organiser record.']),source('FemAsia — contributor biography','https://femasiamagazine.com/author/johny/',['Pulivendula origin, literary roles and Telugu/Hindi/English writing.']),source('Ukiyoto — Nadaka','https://www.ukiyoto.com/product-page/nadaka',['Nadaka title and author.'])],books=[dict(title='Nadaka',detail='Telugu · Ukiyoto Publishing',url='https://www.ukiyoto.com/product-page/nadaka')],identity_match='Name, Pulivendula, languages and specific Vivechani award all match supplied biography; award independently checked with organiser.',poems_read=[dict(id=543,title='Sometimes I Freeze',basis='Full supplied English poem read: immobilisation, liberated blood, tears, fire, rain and final address.')],limitations=['No inferred autobiography or diagnosis from bodily imagery.','Changing book total omitted; no unverified awards added.','English supplied source carries no translator credit; no claim about a missing Telugu original.'],next_action='Author/editor review of narrative and English source provenance.'))
